import{_ as a,C as s,o as i,c as h,j as o,a as l,E as r,a2 as n}from"./chunks/framework.TaNiW7i8.js";const y=JSON.parse('{"title":"Graph","description":"","frontmatter":{"title":"Graph"},"headers":[],"relativePath":"en/guide/graph.md","filePath":"en/guide/graph.md"}'),g={name:"en/guide/graph.md"};function d(p,e,c,u,m,f){const t=s("Capture");return i(),h("div",null,[e[0]||(e[0]=o("h1",{id:"graph",tabindex:"-1"},[l("Graph "),o("a",{class:"header-anchor",href:"#graph","aria-label":'Permalink to "Graph"'},"​")],-1)),e[1]||(e[1]=o("p",null,"The graph draws your memory as a network: each point is a domain, a concept, a project or a note, and each line is a relation between two of them. You can explore it with the mouse or the keyboard, and it updates by itself when the memory changes.",-1)),r(t,{name:"graphe",alt:"The memory graph in the dark theme: a node selected with the keyboard, its relations (broader, more specific, neighbours) listed on the right."}),e[2]||(e[2]=n('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>The graph opens in its own tab, <strong>Graph</strong> (see <a href="/Kessho/en/guide/home.html">Home</a> to get there).</p><ul><li><strong>The header</strong>: the title &quot;Your memory, in relations&quot;, the <strong>Search a note, a project…</strong> field, and two buttons, <strong>View as a list</strong> and <strong>Details</strong>.</li><li><strong>The filter bar</strong>: the <strong>LEVELS</strong> row with one pill per level and its number of points (<strong>Domain</strong>, <strong>Concept</strong>, <strong>Project</strong>, <strong>Note</strong>, <strong>Archives</strong>), the <strong>Belongs to</strong> and <strong>Relations</strong> menus, the <strong>Unfiled</strong> pill and the <strong>Reset</strong> button.</li><li><strong>The drawing</strong>: one point per item, one line per relation. A legend at the bottom left names the levels. At the bottom right, &quot;Titles shown: 14 of 14&quot; says how many labels fit on screen, and three buttons control the zoom (<strong>Zoom out</strong>, <strong>Zoom in</strong>, <strong>Show everything</strong>).</li><li><strong>The details panel</strong>, in the right-hand column: <ul><li>With nothing selected, it reminds you of the keys: &quot;Up and down arrows: go up or down. Left and right arrows: move to a neighbour. Enter: open the note.&quot;</li><li>With a point chosen, it shows &quot;Selected: …&quot;, its level (&quot;Project · Session archives: 4&quot;), the <strong>Open the note</strong> button, then its relations in three groups with their count: <strong>Broader</strong>, <strong>More specific</strong> and <strong>Neighbours</strong>.</li></ul></li></ul><p>Session archives are not drawn by default: they are &quot;folded into their project&quot;, and the <strong>Archives</strong> pill gives their number.</p><p>When the memory has fewer than three relations, there is nothing to draw. The screen says so: &quot;Nothing to link yet. File notes under a project, a domain or a concept and their links will appear here.&quot; If reading fails, it tells you (&quot;The relations could not be read.&quot;) and offers to try again.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="pick-a-point" tabindex="-1">Pick a point <a class="header-anchor" href="#pick-a-point" aria-label="Permalink to &quot;Pick a point&quot;">​</a></h3><p>Click a point: it is selected, and the details panel shows its relations. In the panel, clicking the name of a relation moves the selection to it.</p><p>With the keyboard, put the focus on the drawing (Tab, or a click), then:</p><ul><li><strong>↑</strong> goes to a broader item (the first in the <strong>Broader</strong> list), <strong>↓</strong> goes down to a more specific one;</li><li><strong>←</strong> and <strong>→</strong> move to a neighbour;</li><li>the first key press picks the most connected item among the domains, concepts and projects;</li><li><strong>Esc</strong> clears the selection.</li></ul><h3 id="open-a-point-s-note" tabindex="-1">Open a point&#39;s note <a class="header-anchor" href="#open-a-point-s-note" aria-label="Permalink to &quot;Open a point&#39;s note&quot;">​</a></h3><p>Double-click the point, press <strong>Enter</strong> while it is selected, or click <strong>Open the note</strong> in the details panel. The note opens in a tab (<a href="/Kessho/en/guide/atom.html">Atom and editor</a>).</p><h3 id="move-the-drawing" tabindex="-1">Move the drawing <a class="header-anchor" href="#move-the-drawing" aria-label="Permalink to &quot;Move the drawing&quot;">​</a></h3><p>Drag a point to move it: it stays where you hold it and the rest of the network rearranges around it. Drag the background to pan the drawing.</p><h3 id="zoom" tabindex="-1">Zoom <a class="header-anchor" href="#zoom" aria-label="Permalink to &quot;Zoom&quot;">​</a></h3><ul><li>The <strong>Zoom in</strong> (+), <strong>Zoom out</strong> (−) and <strong>Show everything</strong> (⤢) buttons, at the bottom right of the drawing.</li><li><strong>⌘</strong> (or <strong>Ctrl</strong>) and the mouse wheel, or a pinch on the trackpad. The wheel alone only zooms once the drawing has keyboard focus: otherwise it scrolls the page.</li></ul><h3 id="search-for-a-note" tabindex="-1">Search for a note <a class="header-anchor" href="#search-for-a-note" aria-label="Permalink to &quot;Search for a note&quot;">​</a></h3><p>Click the <strong>Search a note, a project…</strong> field, or type <strong>/</strong> (outside a text field).</p>',18)),r(t,{name:"graphe-recherche",alt:'The graph search: "lu" typed, the matching project is suggested with its level and zone.'}),e[3]||(e[3]=n('<ul><li>Results appear as you type, with their count (&quot;Results: 3&quot;). Matching points get a ring in the drawing.</li><li><strong>↑</strong> and <strong>↓</strong> step through the list. <strong>Enter</strong> centres the drawing on the result and selects it. <strong>⇧ Enter</strong> opens the note.</li><li><strong>Esc</strong> closes the list, a second <strong>Esc</strong> clears the field.</li><li>A result ruled out by a filter stays in the list, faded (&quot;ruled out by the filters&quot;). <strong>Show them</strong> lifts the filters.</li><li>With no result: &quot;No note matches …&quot;, with the advice to try fewer letters or a word from the title.</li></ul><h3 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h3><p>Filters combine: a point has to pass every filter you have set.</p>',3)),r(t,{name:"graphe-filtres",alt:`The graph's "Belongs to" filter, open: "Lighting" is checked and notes outside it are greyed out.`}),e[4]||(e[4]=n('<ul><li><strong>Levels</strong>: click a pill to remove or restore a level. The <strong>Archives</strong> pill unfolds the session archives into the drawing; the memory is then read again.</li><li><strong>Belongs to</strong>: a menu with a search field (<strong>A project or a domain</strong>) and a checkbox per project or domain. Ticking boxes keeps only those items and what descends from them.</li><li><strong>Relations</strong>: <strong>All</strong>, <strong>3 or more</strong>, <strong>10 or more (hubs)</strong> or <strong>No relation</strong>, depending on how many relations each point has.</li><li><strong>Unfiled</strong>: keeps only the notes, concepts and projects that have no parent.</li><li><strong>Ruled-out items</strong>: as soon as a filter is set, choose <strong>Dim</strong> (ruled-out points stay in place, very faint) or <strong>Hide</strong> (they disappear and the drawing rearranges). A line says how many were dimmed or hidden.</li><li><strong>Reset (N)</strong> removes the N filters you have set.</li></ul><h3 id="view-the-memory-as-a-list" tabindex="-1">View the memory as a list <a class="header-anchor" href="#view-the-memory-as-a-list" aria-label="Permalink to &quot;View the memory as a list&quot;">​</a></h3><p><strong>View as a list</strong> replaces the drawing with a list of notes and relations, grouped by level then in alphabetical order. The selection, the search, the filters and the details panel stay the same. <strong>View the graph</strong> returns to the drawing. Your choice is remembered on this computer.</p><p>In a window too narrow for the drawing, the list takes over.</p><h3 id="fold-the-details-panel" tabindex="-1">Fold the details panel <a class="header-anchor" href="#fold-the-details-panel" aria-label="Permalink to &quot;Fold the details panel&quot;">​</a></h3><p>The <strong>Details</strong> button, or the <strong>F</strong> key (outside a text field), folds or reopens the right-hand column to give the drawing all the room.</p><h3 id="let-the-graph-follow-the-memory" tabindex="-1">Let the graph follow the memory <a class="header-anchor" href="#let-the-graph-follow-the-memory" aria-label="Permalink to &quot;Let the graph follow the memory&quot;">​</a></h3><p>Nothing to do: when the memory changes (an agent writes, you edit a note), the graph reads it again within a few seconds. If you switch to another tab, the graph keeps its place, zoom, selection, filters and search for when you come back.</p>',8))])}const b=a(g,[["render",d]]);export{y as __pageData,b as default};
